public static boolean checkCleartextTrafficPermitted(Uri... uris) {
  if (Util.SDK_INT < 24) {
    return true;
  }
  for (Uri uri : uris) {
    try {
      if ("http".equals(uri.getScheme()) && !NetworkSecurityPolicy.getInstance().isCleartextTrafficPermitted(Assertions.checkNotNull(uri.getHost()))) {
        return false;
      }
    } catch (NullPointerException e) {
      // Handle the case where uri.getHost() is null
      return false;
    }
  }
  return true;
}
